import React from 'react';
import { useForm } from 'react-hook-form';
import { UserInfo } from '../../types/user';

interface UserInfoFormProps {
  defaultValues: Partial<UserInfo>;
  onNext: (data: Partial<UserInfo>) => void;
}

const UserInfoForm: React.FC<UserInfoFormProps> = ({ defaultValues, onNext }) => {
  const { register, handleSubmit, setValue, watch, formState: { errors } } = useForm<UserInfo>({
    defaultValues: defaultValues,
  });

  const profilePhoto = watch("profilePhoto");

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setValue("profilePhoto", reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const onSubmit = (data: UserInfo) => {
    onNext(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
      <div>
        <label htmlFor="profilePhoto" className="block text-sm font-medium text-gray-700">Profile Photo</label>
        <input
          type="file"
          id="profilePhoto"
          accept="image/*"
          onChange={handleFileChange}
          className="mt-1 block w-full text-sm text-gray-500
            file:mr-4 file:py-2 file:px-4
            file:rounded-full file:border-0
            file:text-sm file:font-semibold
            file:bg-indigo-50 file:text-indigo-700
            hover:file:bg-indigo-100"
        />
        {profilePhoto && typeof profilePhoto === 'string' && (
          <div className="mt-2">
            <img src={profilePhoto} alt="Profile Preview" className="h-20 w-20 rounded-full object-cover" />
          </div>
        )}
        {errors.profilePhoto && <p className="mt-2 text-sm text-red-600">{errors.profilePhoto.message}</p>}
      </div>

      <div>
        <label htmlFor="firstName" className="block text-sm font-medium text-gray-700">First Name</label>
        <input
          type="text"
          id="firstName"
          {...register("firstName", { required: "First Name is required" })}
          className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        />
        {errors.firstName && <p className="mt-2 text-sm text-red-600">{errors.firstName.message}</p>}
      </div>

      <div>
        <label htmlFor="lastName" className="block text-sm font-medium text-gray-700">Last Name</label>
        <input
          type="text"
          id="lastName"
          {...register("lastName", { required: "Last Name is required" })}
          className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        />
        {errors.lastName && <p className="mt-2 text-sm text-red-600">{errors.lastName.message}</p>}
      </div>

      <div>
        <label htmlFor="dob" className="block text-sm font-medium text-gray-700">Date of Birth</label>
        <input
          type="date"
          id="dob"
          {...register("dob", { required: "Date of Birth is required" })}
          className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        />
        {errors.dob && <p className="mt-2 text-sm text-red-600">{errors.dob.message}</p>}
      </div>

      <div>
        <label htmlFor="occupation" className="block text-sm font-medium text-gray-700">Occupation</label>
        <input
          type="text"
          id="occupation"
          {...register("occupation", { required: "Occupation is required" })}
          className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        />
        {errors.occupation && <p className="mt-2 text-sm text-red-600">{errors.occupation.message}</p>}
      </div>

      <div>
        <label htmlFor="gender" className="block text-sm font-medium text-gray-700">Gender</label>
        <select
          id="gender"
          {...register("gender", { required: "Gender is required" })}
          className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        >
          <option value="">Select Gender</option>
          <option value="Male">Male</option>
          <option value="Female">Female</option>
          <option value="Other">Other</option>
        </select>
        {errors.gender && <p className="mt-2 text-sm text-red-600">{errors.gender.message}</p>}
      </div>

      <div className="flex justify-end">
        <button
          type="submit"
          className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
        >
          Next
        </button>
      </div>
    </form>
  );
};

export default UserInfoForm;