import React, { useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import toast from 'react-hot-toast';
import { fetchUserById, updateUser } from '../features/users/userSlice';
import { updateUserInfo, updateUserContact, updateUserAddress, updateUserAcademics, resetForm } from '../features/form/formSlice';
import { RootState, AppDispatch } from '../store/store';
import Spinner from '../components/Spinner';
import Error from '../components/Error';
import MultiStepForm from '../components/MultiStepForm';
import { User } from '../types/user';

const EditUserPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const { currentUser, loading, error } = useSelector((state: RootState) => state.user);

  useEffect(() => {
    if (id) {
      dispatch(fetchUserById(id));
    }
  }, [id, dispatch]);

  useEffect(() => {
    if (currentUser) {
      dispatch(updateUserInfo(currentUser.userInfo));
      dispatch(updateUserContact(currentUser.userContact));
      dispatch(updateUserAddress(currentUser.userAddress));
      dispatch(updateUserAcademics(currentUser.userAcademics));
    }
  }, [currentUser, dispatch]);

  const handleSubmit = async (formData: User) => {
    if (!id) return;
    try {
      await dispatch(updateUser({ id, userData: formData })).unwrap();
      toast.success('User updated successfully!');
      dispatch(resetForm()); // Reset form after submission
      navigate('/view-users');
    } catch (err: any) {
      toast.error(`Failed to update user: ${err.message || err}`);
    }
  };

  if (loading) {
    return <Spinner />;
  }

  if (error) {
    return <Error message={error} />;
  }

  if (!currentUser) {
    return (
      <div className="bg-white shadow overflow-hidden sm:rounded-lg p-6">
        <h1 className="text-3xl font-bold text-gray-900 mb-6">Edit User</h1>
        <p className="text-gray-700">User not found for editing.</p>
      </div>
    );
  }

  return (
    <div className="bg-white shadow overflow-hidden sm:rounded-lg p-6">
      <h1 className="text-3xl font-bold text-gray-900 mb-6">Edit User</h1>
      <MultiStepForm onSubmit={handleSubmit} />
    </div>
  );
};

export default EditUserPage;
