import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { RootState } from '../store/store';
import { updateUserInfo, updateUserContact, updateUserAddress, updateUserAcademics, resetForm } from '../features/form/formSlice';
import ProgressBar from './ProgressBar';
import UserInfoForm from './forms/UserInfoForm';
import UserContactForm from './forms/UserContactForm';
import UserAddressForm from './forms/UserAddressForm';
import UserAcademicsForm from './forms/UserAcademicsForm';
import ResumePreview from './ResumePreview';
import { User, UserAcademics } from '../types/user';

interface MultiStepFormProps {
  onSubmit: (data: User) => void;
}

const MultiStepForm: React.FC<MultiStepFormProps> = ({ onSubmit }) => {
  const [currentStep, setCurrentStep] = useState(1);
  const dispatch = useDispatch();
  const formData = useSelector((state: RootState) => state.form);

  const totalSteps = 5; // UserInfo, UserContact, UserAddress, UserAcademics, ResumePreview

  const handleNext = (newData: any) => {
    switch (currentStep) {
      case 1:
        dispatch(updateUserInfo(newData));
        break;
      case 2:
        dispatch(updateUserContact(newData));
        break;
      case 3:
        dispatch(updateUserAddress(newData));
        break;
      case 4:
        dispatch(updateUserAcademics(newData));
        break;
      default:
        break;
    }
    setCurrentStep((prev) => prev + 1);
  };

  const handleBack = () => {
    setCurrentStep((prev) => prev - 1);
  };

  const handleSubmit = () => {
    // The formData from Redux is already the complete data
    onSubmit(formData as User);
    dispatch(resetForm()); // Reset form after submission
  };

  const renderStep = () => {
    switch (currentStep) {
      case 1:
        return <UserInfoForm defaultValues={formData.userInfo} onNext={handleNext} />;
      case 2:
        return <UserContactForm defaultValues={formData.userContact} onNext={handleNext} onBack={handleBack} />;
      case 3:
        return <UserAddressForm defaultValues={formData.userAddress} onNext={handleNext} onBack={handleBack} />;
      case 4:
        return <UserAcademicsForm defaultValues={{ userAcademics: formData.userAcademics as UserAcademics[] }} onNext={handleNext} onBack={handleBack} />;
      case 5:
        return <ResumePreview formData={formData as User} onBack={handleBack} onSubmit={handleSubmit} />;
      default:
        return null;
    }
  };

  return (
    <div className="flex">
      <div className="w-1/4 p-4">
        <ProgressBar currentStep={currentStep} totalSteps={totalSteps} />
      </div>
      <div className="w-3/4 p-4">
        {renderStep()}
      </div>
    </div>
  );
};

export default MultiStepForm;
