import React from 'react';
import { useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import MultiStepForm from '../components/MultiStepForm';
import { createUser } from '../features/users/userSlice';
import { User } from '../types/user';
import { AppDispatch } from '../store/store';

const CreateUserPage: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();

  const handleSubmit = async (data: User) => {
    try {
      // The 'id' field is typically generated by the backend, so we omit it when creating
      const { id, ...userDataWithoutId } = data;
      await dispatch(createUser(userDataWithoutId)).unwrap();
      toast.success('User created successfully!');
      navigate('/view-users'); // Navigate to user list after successful creation
    } catch (error: any) {
      toast.error(`Failed to create user: ${error.message || error}`);
    }
  };

  return (
    <div className="bg-white shadow overflow-hidden sm:rounded-lg p-6">
      <h1 className="text-3xl font-bold text-gray-900 mb-6">Create New User</h1>
      <MultiStepForm onSubmit={handleSubmit} />
    </div>
  );
};

export default CreateUserPage;