import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { UserInfo, UserContact, UserAddress, UserAcademics } from '../../types/user';

interface FormState {
  userInfo: Partial<UserInfo>;
  userContact: Partial<UserContact>;
  userAddress: Partial<UserAddress>;
  userAcademics: Partial<UserAcademics>[];
}

const initialState: FormState = {
  userInfo: {},
  userContact: {},
  userAddress: {},
  userAcademics: [],
};

const formSlice = createSlice({
  name: 'form',
  initialState,
  reducers: {
    updateUserInfo: (state, action: PayloadAction<Partial<UserInfo>>) => {
      state.userInfo = { ...state.userInfo, ...action.payload };
    },
    updateUserContact: (state, action: PayloadAction<Partial<UserContact>>) => {
      state.userContact = { ...state.userContact, ...action.payload };
    },
    updateUserAddress: (state, action: PayloadAction<Partial<UserAddress>>) => {
      state.userAddress = { ...state.userAddress, ...action.payload };
    },
    updateUserAcademics: (state, action: PayloadAction<Partial<UserAcademics>[]>) => {
      state.userAcademics = action.payload;
    },
    resetForm: (state) => {
      state.userInfo = {};
      state.userContact = {};
      state.userAddress = {};
      state.userAcademics = [];
    },
  },
});

export const { updateUserInfo, updateUserContact, updateUserAddress, updateUserAcademics, resetForm } = formSlice.actions;

export default formSlice.reducer;