import React from 'react';
import { User, UserAcademics } from '../types/user';

interface ResumePreviewProps {
  formData: Partial<User>;
  onBack: () => void;
  onSubmit: () => void;
}

const ResumePreview: React.FC<ResumePreviewProps> = ({ formData, onBack, onSubmit }) => {
  const { userInfo, userContact, userAddress, userAcademics } = formData;

  return (
    <div className="bg-white shadow overflow-hidden sm:rounded-lg p-6">
      <h2 className="text-2xl font-bold text-gray-900 mb-4">Resume Preview</h2>

      {/* Profile Photo */}
      {userInfo?.profilePhoto && typeof userInfo.profilePhoto === 'string' && (
        <div className="mb-6 flex justify-center">
          <img src={userInfo.profilePhoto} alt="Profile" className="h-32 w-32 rounded-full object-cover border-4 border-indigo-200 shadow-lg" />
        </div>
      )}

      {/* Personal Information */}
      {userInfo && (
        <div className="mb-6">
          <h3 className="text-xl font-semibold text-gray-800 border-b pb-2 mb-3">Personal Information</h3>
          <p><strong>Name:</strong> {userInfo.firstName} {userInfo.lastName}</p>
          <p><strong>Date of Birth:</strong> {userInfo.dob}</p>
          <p><strong>Occupation:</strong> {userInfo.occupation}</p>
          <p><strong>Gender:</strong> {userInfo.gender}</p>
        </div>
      )}

      {/* Contact Information */}
      {userContact && (
        <div className="mb-6">
          <h3 className="text-xl font-semibold text-gray-800 border-b pb-2 mb-3">Contact Information</h3>
          <p><strong>Email:</strong> {userContact.email}</p>
          <p><strong>Phone:</strong> {userContact.phoneNumber}</p>
          {userContact.fax && <p><strong>Fax:</strong> {userContact.fax}</p>}
          {userContact.linkedinUrl && <p><strong>LinkedIn:</strong> <a href={userContact.linkedinUrl} target="_blank" rel="noopener noreferrer" className="text-indigo-600 hover:underline">{userContact.linkedinUrl}</a></p>}
        </div>
      )}

      {/* Address Information */}
      {userAddress && (
        <div className="mb-6">
          <h3 className="text-xl font-semibold text-gray-800 border-b pb-2 mb-3">Address Information</h3>
          <p><strong>Address:</strong> {userAddress.address}, {userAddress.city}, {userAddress.state}, {userAddress.zipCode}, {userAddress.country}</p>
        </div>
      )}

      {/* Academic Information */}
      {userAcademics && userAcademics.length > 0 && (
        <div className="mb-6">
          <h3 className="text-xl font-semibold text-gray-800 border-b pb-2 mb-3">Academic Information</h3>
          {userAcademics.map((academic: UserAcademics, index: number) => (
            <p key={index}><strong>School Name:</strong> {academic.schoolName}</p>
          ))}
        </div>
      )}

      <div className="flex justify-between mt-6">
        <button
          type="button"
          onClick={onBack}
          className="inline-flex justify-center py-2 px-4 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
        >
          Back
        </button>
        <button
          type="button"
          onClick={onSubmit}
          className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
        >
          Submit
        </button>
      </div>
    </div>
  );
};

export default ResumePreview;