import React from 'react';
import { useForm, useFieldArray } from 'react-hook-form';
import { UserAcademics } from '../../types/user';

interface UserAcademicsFormProps {
  defaultValues: { userAcademics: UserAcademics[] };
  onNext: (data: { userAcademics: UserAcademics[] }) => void;
  onBack: () => void;
}

const UserAcademicsForm: React.FC<UserAcademicsFormProps> = ({ defaultValues, onNext, onBack }) => {
  const { register, handleSubmit, control, formState: { errors } } = useForm<{ userAcademics: UserAcademics[] }>({
    defaultValues: defaultValues,
  });

  const { fields, append, remove } = useFieldArray({
    control,
    name: "userAcademics",
  });

  const onSubmit = (data: { userAcademics: UserAcademics[] }) => {
    onNext(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
      <h2 className="text-xl font-bold text-gray-900">Academic Information</h2>
      {fields.map((item, index) => (
        <div key={item.id} className="border p-4 rounded-md space-y-2">
          <div>
            <label htmlFor={`userAcademics.${index}.schoolName`} className="block text-sm font-medium text-gray-700">School Name</label>
            <input
              type="text"
              id={`userAcademics.${index}.schoolName`}
              {...register(`userAcademics.${index}.schoolName`, { required: "School Name is required" })}
              className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
            />
            {errors.userAcademics?.[index]?.schoolName && <p className="mt-2 text-sm text-red-600">{errors.userAcademics[index]?.schoolName?.message}</p>}
          </div>
          <button
            type="button"
            onClick={() => remove(index)}
            className="text-red-600 hover:text-red-900 text-sm"
          >
            Remove Academic Entry
          </button>
        </div>
      ))}

      <button
        type="button"
        onClick={() => append({ schoolName: "" })}
        className="inline-flex justify-center py-2 px-4 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
      >
        Add Academic Entry
      </button>

      <div className="flex justify-between">
        <button
          type="button"
          onClick={onBack}
          className="inline-flex justify-center py-2 px-4 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
        >
          Back
        </button>
        <button
          type="submit"
          className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
        >
          Next
        </button>
      </div>
    </form>
  );
};

export default UserAcademicsForm;
