import React, { useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { fetchUserById } from '../features/users/userSlice';
import { RootState, AppDispatch } from '../store/store';
import Spinner from '../components/Spinner';
import Error from '../components/Error';
import ResumePreview from '../components/ResumePreview';
import { User } from '../types/user';

const ViewUserPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const dispatch = useDispatch<AppDispatch>();
  const { currentUser, loading, error } = useSelector((state: RootState) => state.user);

  useEffect(() => {
    if (id) {
      dispatch(fetchUserById(id));
    }
  }, [id, dispatch]);

  if (loading) {
    return <Spinner />;
  }

  if (error) {
    return <Error message={error} />;
  }

  if (!currentUser) {
    return (
      <div className="bg-white shadow overflow-hidden sm:rounded-lg p-6">
        <h1 className="text-3xl font-bold text-gray-900 mb-6">User Resume View</h1>
        <p className="text-gray-700">User not found.</p>
      </div>
    );
  }

  return (
    <div className="bg-white shadow overflow-hidden sm:rounded-lg p-6">
      <h1 className="text-3xl font-bold text-gray-900 mb-6">User Resume View</h1>
      <ResumePreview formData={currentUser} onBack={() => {}} onSubmit={() => {}} />
    </div>
  );
};

export default ViewUserPage;
