import React from 'react';
import { useForm } from 'react-hook-form';
import { UserAddress } from '../../types/user';

interface UserAddressFormProps {
  defaultValues: Partial<UserAddress>;
  onNext: (data: Partial<UserAddress>) => void;
  onBack: () => void;
}

const UserAddressForm: React.FC<UserAddressFormProps> = ({ defaultValues, onNext, onBack }) => {
  const { register, handleSubmit, formState: { errors } } = useForm<UserAddress>({
    defaultValues: defaultValues,
  });

  const onSubmit = (data: UserAddress) => {
    onNext(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
      <div>
        <label htmlFor="address" className="block text-sm font-medium text-gray-700">Address</label>
        <input
          type="text"
          id="address"
          {...register("address", { required: "Address is required" })}
          className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        />
        {errors.address && <p className="mt-2 text-sm text-red-600">{errors.address.message}</p>}
      </div>

      <div>
        <label htmlFor="city" className="block text-sm font-medium text-gray-700">City</label>
        <input
          type="text"
          id="city"
          {...register("city", { required: "City is required" })}
          className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        />
        {errors.city && <p className="mt-2 text-sm text-red-600">{errors.city.message}</p>}
      </div>

      <div>
        <label htmlFor="state" className="block text-sm font-medium text-gray-700">State</label>
        <input
          type="text"
          id="state"
          {...register("state", { required: "State is required" })}
          className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        />
        {errors.state && <p className="mt-2 text-sm text-red-600">{errors.state.message}</p>}
      </div>

      <div>
        <label htmlFor="country" className="block text-sm font-medium text-gray-700">Country</label>
        <input
          type="text"
          id="country"
          {...register("country", { required: "Country is required" })}
          className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        />
        {errors.country && <p className="mt-2 text-sm text-red-600">{errors.country.message}</p>}
      </div>

      <div>
        <label htmlFor="zipCode" className="block text-sm font-medium text-gray-700">Zip Code</label>
        <input
          type="text"
          id="zipCode"
          {...register("zipCode", { required: "Zip Code is required" })}
          className="mt-1 block w-full border border-gray-300 rounded-md shadow-sm py-2 px-3 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        />
        {errors.zipCode && <p className="mt-2 text-sm text-red-600">{errors.zipCode.message}</p>}
      </div>

      <div className="flex justify-between">
        <button
          type="button"
          onClick={onBack}
          className="inline-flex justify-center py-2 px-4 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
        >
          Back
        </button>
        <button
          type="submit"
          className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
        >
          Next
        </button>
      </div>
    </form>
  );
};

export default UserAddressForm;
